import Modal from 'flarum/common/components/Modal';
import Stream from 'flarum/common/utils/Stream';
import { t } from '../utils/settings';
import { SHORTCUT_GROUPS } from '../shell/shortcuts';

/** Os nomes das teclas como aparecem nas pílulas de atalho. */
const KEY_NAMES = {
  shift: 'Shift',
  ctrl: 'Ctrl',
  alt: 'Alt',
  meta: 'Meta',
  enter: 'Enter',
  home: 'Home',
  end: 'End',
  esc: 'Esc'
};

/** "g h" → ["G", "H"]; "shift+j" → ["Shift", "J"]. */
function keyParts(combo) {
  return combo.split(/[\s+]+/).filter(Boolean).map(key => KEY_NAMES[key.toLowerCase()] || (key.length === 1 ? key.toUpperCase() : key));
}

/**
 * A janela de atalhos, aberta pela
 * tecla "?": o campo de busca no topo e, em duas colunas, uma caixa por grupo
 * com a descrição à esquerda e as teclas em pílulas à direita. O corpo rola
 * dentro do modal (80% da altura), em vez de empurrar a página.
 */
export default class KeyboardShortcutsModal extends Modal {
  filter = Stream('');
  className() {
    return 'CanelaShortcutsModal Modal--large';
  }
  title() {
    return t('shortcuts.title');
  }
  onready() {
    this.$('.CanelaShortcuts-filter').trigger('focus');
  }
  matches(shortcut, needle) {
    if (!needle) return true;
    const label = String(t(`shortcuts.actions.${shortcut.action}`)).toLowerCase();
    const keys = shortcut.keys.map(combo => keyParts(combo).join(' ').toLowerCase());
    return label.includes(needle) || keys.some(combo => combo.includes(needle));
  }
  content() {
    const needle = this.filter().trim().toLowerCase();
    const groups = SHORTCUT_GROUPS.map(group => ({
      ...group,
      shortcuts: group.shortcuts.filter(shortcut => this.matches(shortcut, needle))
    })).filter(group => group.shortcuts.length > 0);
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "CanelaShortcuts-search"
    }, m("input", {
      className: "FormControl CanelaShortcuts-filter",
      type: "search",
      bidi: this.filter,
      placeholder: t('shortcuts.search_placeholder')
    })), groups.length ? m("div", {
      className: "CanelaShortcuts"
    }, groups.map(group => m("section", {
      className: "CanelaShortcuts-group"
    }, m("h4", null, t(`shortcuts.groups.${group.name}`)), m("table", null, m("tbody", null, group.shortcuts.map(shortcut => m("tr", null, m("td", {
      className: "CanelaShortcuts-label"
    }, t(`shortcuts.actions.${shortcut.action}`)), m("td", {
      className: "CanelaShortcuts-keys"
    }, shortcut.keys.map((combo, index) => [index > 0 && m("span", {
      className: "CanelaShortcuts-or"
    }, /next_prev|first_last/.test(shortcut.action) ? '/' : t('shortcuts.or')), m("kbd", {
      className: "CanelaShortcuts-kbd"
    }, keyParts(combo).map(key => m("span", {
      className: "CanelaShortcuts-key"
    }, key)))]))))))))) : m("p", {
      className: "CanelaShortcuts-empty"
    }, t('shortcuts.no_results')));
  }
}
flarum.reg.add('ramon-canela', 'forum/components/KeyboardShortcutsModal', KeyboardShortcutsModal);